import sys
sys.setrecursionlimit(200000)

def main():
    input = sys.stdin.read
    data = input().split()

    idx = 0
    n = int(data[idx]); idx += 1

    if n == 1:
        print(1)
        print("1 1")
        return

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    size = [0] * (n + 1)
    order = []

    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                depth[v] = depth[u] + 1
                stack.append(v)

    for u in reversed(order):
        sz = 1
        for v in adj[u]:
            if v != parent[u]:
                sz += size[v]
        size[u] = sz

    def get_centroid_subtree(root):
        total = size[root]
        curr = root
        p = parent[curr]
        while True:
            found = False
            for v in adj[curr]:
                if v != p and size[v] > total // 2:
                    curr = v
                    p = parent[curr]
                    found = True
                    break
            if not found:
                break
        return curr

    centroids = []
    centroid_map = {}

    for u in order:
        if parent[u] == 0:
            continue
        p = parent[u]
        if size[u] * 2 > size[p]:
            c = get_centroid_subtree(p)
            if c not in centroid_map:
                centroid_map[c] = len(centroids)
                centroids.append(c)

    nodes_list = []
    for c in centroids:
        subset = []
        stack = [c]
        seen = {c}
        while stack:
            u = stack.pop()
            subset.append(u)
            for v in adj[u]:
                if v != parent[u] and v not in seen:
                    seen.add(v)
                    stack.append(v)
                elif v == parent[u]:
                    pass
        nodes_list.append(subset)

    if not centroids:
        nodes_list = [[i] for i in range(1, n + 1)]

    m = len(nodes_list)
    print(m)
    for subset in nodes_list:
        print(f"{len(subset)} {' '.join(map(str, sorted(subset)))}")

    if m > 1:
        for i in range(m - 1):
            print(f"{i + 1} {i + 2}")

if __name__ == "__main__":
    main()
